#!/usr/bin/env python3
"""A tiny to-do list CLI with JSON-file persistence.

See SPEC.md for the full behavioural specification.
"""

import json
import os
import sys

STORAGE_FILE = "todo.json"


class UsageError(Exception):
    """Malformed invocation (maps to exit code 2)."""


class RuntimeTodoError(Exception):
    """Well-formed invocation that fails at runtime (maps to exit code 1)."""


def _storage_path():
    return os.path.join(os.getcwd(), STORAGE_FILE)


def load_todos():
    path = _storage_path()
    if not os.path.isfile(path):
        return []

    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except (OSError, json.JSONDecodeError) as exc:
        raise RuntimeTodoError(f"todo: storage file contains invalid JSON: {exc}")

    if not isinstance(data, list):
        raise RuntimeTodoError("todo: storage file has invalid schema")

    for item in data:
        if (
            not isinstance(item, dict)
            or set(item.keys()) != {"id", "text", "done"}
            or not isinstance(item.get("id"), int)
            or isinstance(item.get("id"), bool)
            or not isinstance(item.get("text"), str)
            or not isinstance(item.get("done"), bool)
        ):
            raise RuntimeTodoError("todo: storage file has invalid schema")

    return data


def save_todos(todos):
    path = _storage_path()
    with open(path, "w", encoding="utf-8") as f:
        json.dump(todos, f)


def cmd_add(args):
    if len(args) != 1:
        raise UsageError("todo: add requires exactly one <text> argument")

    text = args[0]
    todos = load_todos()
    next_id = (max((t["id"] for t in todos), default=0)) + 1
    todos.append({"id": next_id, "text": text, "done": False})
    save_todos(todos)
    print(next_id)
    return 0


def cmd_list(args):
    if len(args) != 0:
        raise UsageError("todo: list takes no arguments")

    todos = load_todos()
    for todo in sorted(todos, key=lambda t: t["id"]):
        mark = "x" if todo["done"] else " "
        print(f"{todo['id']} [{mark}] {todo['text']}")
    return 0


def cmd_done(args):
    if len(args) != 1:
        raise UsageError("todo: done requires exactly one <id> argument")

    try:
        target_id = int(args[0])
    except ValueError:
        raise UsageError(f"todo: invalid id (not an integer): {args[0]!r}")

    todos = load_todos()
    for todo in todos:
        if todo["id"] == target_id:
            todo["done"] = True
            save_todos(todos)
            return 0

    raise RuntimeTodoError(f"todo: no todo with id {target_id}")


COMMANDS = {
    "add": cmd_add,
    "list": cmd_list,
    "done": cmd_done,
}


def main(argv):
    if not argv:
        print("todo: missing command (expected add, list, or done)", file=sys.stderr)
        return 2

    command, rest = argv[0], argv[1:]
    handler = COMMANDS.get(command)
    if handler is None:
        print(f"todo: unknown command: {command!r}", file=sys.stderr)
        return 2

    try:
        return handler(rest)
    except UsageError as exc:
        print(str(exc), file=sys.stderr)
        return 2
    except RuntimeTodoError as exc:
        print(str(exc), file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

